desired_validation.text:
func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func validateManagedMemberLaunch(launch ManagedMemberLaunch, d Desired, r Registration) error {
	if len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
		return errors.New("managed desired cannot carry arbitrary arguments or environment")
	}
	if validateDigest(launch.SourceDigest) != nil ||
		!strings.HasPrefix(launch.VolumeID, "ocid1.volume.") ||
		!strings.HasPrefix(launch.AttachmentID, "ocid1.volumeattachment.") ||
		len(launch.VolumeID) > 255 || len(launch.AttachmentID) > 255 ||
		strings.ContainsFunc(launch.VolumeID, unicode.IsSpace) || strings.ContainsFunc(launch.AttachmentID, unicode.IsSpace) ||
		launch.Authority.Epoch == 0 ||
		!lowerHex(launch.Authority.ConfigurationID, 64) ||
		!lowerHex(launch.Authority.CertificateSHA256, 64) ||
		!lowerHex(launch.Authority.TLSLeafSHA256, 64) {
		return errors.New("managed launch source, volume or authority is invalid")
	}
	if d.Withdrawn {
		if launch.ProcessMemoryBytes != 0 || launch.MemoryHeadroomBytes != 0 || launch.CgroupMemoryMaxBytes != 0 || launch.SystemReserveBytes != 0 || launch.Runtime != nil {
			return errors.New("withdrawn managed desired contains memory execution data")
		}
		return nil
	}
	const gib = uint64(1 << 30)
	p, h, c := launch.ProcessMemoryBytes, launch.MemoryHeadroomBytes, launch.CgroupMemoryMaxBytes
	if p < 4*gib || h < max(gib, p/4) || h >= p || launch.SystemReserveBytes == 0 ||
		launch.SystemReserveBytes > math.MaxInt64 || launch.SystemReserveBytes != uint64(r.SystemReserveBytes) ||
		validateCgroupMemoryMax(c) != nil || c < p || c > uint64(r.Capacity.MemoryBytes) ||
		p > math.MaxInt64 || h > math.MaxInt64 || p%uint64(os.Getpagesize()) != 0 || h%uint64(os.Getpagesize()) != 0 {
		return errors.New("managed process memory, headroom or cgroup cap is invalid")
	}
	if launch.Runtime != nil {
		if launch.AttachmentETag == "" {
			return errors.New("managed runtime requires an exact attachment ETag")
		}
		if err := validateManagedRuntimePins(*launch.Runtime); err != nil {
			return err
		}
	}
	return nil
}

vault_ref_validation.text:
func FileKey(key string) bool { return strings.HasSuffix(key, "_FILE") }

// MaxRefs bounds a workload's secrets, as profiles bound their environment.
const MaxRefs = 64

// maxResolved bounds a workload's resolved secrets together, below the
// native exec request limit, so an oversized set fails before the launch.
const maxResolved = 96 << 10

var (
	vaultOCIDRE = regexp.MustCompile(`^ocid1\.vault\.oc1\.([a-z0-9-]+)\.[a-z0-9]+(?:\.[a-z0-9]+)*$`)
	envKeyRE    = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
	// infrastructure are the cell's own secret families (docs/secrets.md).
	// A role that is, extends or prefixes one names no secrets, so no
	// workload reaches the NetBird, origin, trust or Cloudflare secrets its
	// host may read.
	infrastructure = []string{"api", "cloudflare", "netbird", "orch", "trust", "ts-dashboard", "ts-orchestrator"}
)

// region is the OCI region of the ref's Vault, or "" when the OCID names none.
func (r Ref) region() string {
	match := vaultOCIDRE.FindStringSubmatch(r.Vault)
	if match == nil || len(r.Vault) > 255 || !catalog.IsOCIRegion(match[1]) {
		return ""
	}
	return match[1]
}

// ValidateRefs checks the secrets of role in cell. Each key is an environment
// name that env does not also set. Each ref names a Vault in the cell's own
// OCI region and a secret <cell>-<n>-<role>-<key>, so a profile reaches only
// its own role's secrets even where its host may read more: controllers read
// their whole compartment. Names are prefixes, so the controller also refuses
// a role with secrets beside a role that extends its name (role "foo" would
// otherwise reach "foo-bar"'s), and only a root may add or change a ref
// (cellspec.AuthorityChanges), which pins the Vault.
func ValidateRefs(cell, role string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs {
		return fmt.Errorf("%s has more than %d Vault secrets", role, MaxRefs)
	}
	if len(refs) != 0 && slices.ContainsFunc(infrastructure, func(family string) bool {
		return role == family || strings.HasPrefix(role, family+"-") || strings.HasPrefix(family, role+"-")
	}) {
		return fmt.Errorf("role %s shares a name with the cell's infrastructure secrets and names no Vault secrets", role)
	}
	return ValidateDeliveryRefs(cell, role, refs, env)
}

// ValidateDeliveryRefs binds a privileged delivery to one regional service.
// Workload profiles also apply ValidateRefs's infrastructure-name restriction.
func ValidateDeliveryRefs(cell, service string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs || !nameRE.MatchString(service) {
		return errors.New("Vault delivery needs a service name and at most 64 references")
	}
	entry, known := catalog.LookupName(cell)
	files := map[string]bool{}
	for key, ref := range refs {
		if !known || ref.region() != entry.OCIRegion {
			return fmt.Errorf("Vault secret %s of %s must name a Vault in cell %s's region", key, service, cell)
		}
		if !envKeyRE.MatchString(key) {
			return fmt.Errorf("Vault secret key %q of %s is not an environment name", key, service)
		}
		if _, set := env[key]; set {
			return fmt.Errorf("%s sets %s both in env and as a Vault secret", service, key)
		}
		if files[strings.ToLower(key)] {
			return errors.New("Vault secret keys must name distinct files after lowercasing")
		}
		files[strings.ToLower(key)] = true
		rest, inCell := strings.CutPrefix(ref.Name, cell+"-")
		secretKey, ofService := strings.CutPrefix(rest, service+"-")
		if !ofService {
			// Existing signed profiles retain their cell-number namespace.
			index, legacy, _ := strings.Cut(rest, "-")
			secretKey, ofService = strings.CutPrefix(legacy, service+"-")
			ofService = ofService && index != "" && index[0] != '0' && strings.Trim(index, "0123456789") == ""
		}
		if len(ref.Name) > 255 || !nameRE.MatchString(ref.Name) || !inCell || !ofService || secretKey == "" {
			return fmt.Errorf("Vault secret %s of %s must name %s-%s-<purpose> or an existing %s-<n>-%s-<purpose>", key, service, cell, service, cell, service)
		}
	}
	return nil
}

reserved_identity.text:
// Grants is the per-role list. Add a role or a bucket here; its members get
// it at their next credential renewal.
var Grants = map[string]Grant{
	// TS-633's backup shipper lease; TerraBase's NatsLeaseStore binds it.
	// TS-643's cross-region pulls: members answer terrabase-wan queries in
	// their cell and ask other cells' members over the interregion links.
	// TS-806's live stats: members answer terrabase-stats detail requests in
	// their cell and publish their rollup on their cell's obs.terrabase.
	"terrabase": {EnvPrefix: "TERRABASE_NATS_", Buckets: []Bucket{
		{Name: "terrabase_backup_leases", TTL: 15 * time.Second, History: 1, Memory: true},
	}, Queries: []string{"terrabase-wan", "terrabase-stats"}, Observations: []string{"terrabase"}},
}

// Reserved reports whether key is a launch setting the host sets for role's
// NATS identity, which a profile may not set.
func Reserved(role, key string) bool {
	grant, granted := Grants[role]
	return granted && strings.HasPrefix(key, grant.EnvPrefix)
}

resolve_secrets.text:
func (a *Agent) resolveSecrets(ctx context.Context, d Desired) (map[string]string, error) {
	if len(d.Secrets) == 0 {
		return nil, nil
	}
	if a.cfg.SecretResolver == nil {
		return nil, errors.New(d.Role + " needs Vault secrets, which this host cannot read")
	}
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	values, err := a.cfg.SecretResolver(ctx, d.Secrets)
	if err != nil {
		return nil, err
	}
	// Exactly the named secrets, so a resolver never adds another.
	for key := range d.Secrets {
		if _, ok := values[key]; !ok {
			return nil, fmt.Errorf("Vault secret %s was not read", key)
		}
	}
	if len(values) != len(d.Secrets) {
		return nil, errors.New("Vault secret resolver returned secrets the desired does not name")
	}
	return values, nil
}

session_held.text:
func sessionHeld(old session, r Registration, now time.Time) bool {
	return now.Before(old.ExpiresAt) && (old.RegistrationGeneration == r.Generation || r.ManagedOCI == nil)
}

function_transport.text:
type functionMaterialTransport struct {
	controller        *Controller
	conn              *nats.Conn
	authority         *authority.Runtime
	proof             release.VerifiedFunction
	binding           FunctionMaterialBinding
	grant             authority.FunctionBinding
	files             map[string][]byte
	expires           time.Time
	credentialExpires time.Time
	hostKey           ed25519.PrivateKey
	responseKey       ed25519.PrivateKey
}

func (f *functionMaterialTransport) current(ctx context.Context, registration Registration, binding FunctionMaterialBinding) (FunctionMaterialFiles, error) {
	// This fixture resolves the authenticated registration before consulting the
	// real durable grant. Query fields alone cannot select another recipient.
	if registration.Node != "function-host" || registration.ID != f.binding.HostID ||
		binding != f.binding {
		return FunctionMaterialFiles{}, errors.New("recipient differs from admitted host task")
	}
	if err := f.authority.VerifyFunctionGrant(ctx, f.proof, f.grant); err != nil {
		return FunctionMaterialFiles{}, err
	}
	files := maps.Clone(f.files)
	for name, content := range files {
		files[name] = bytes.Clone(content)
	}
	return FunctionMaterialFiles{Files: files, ExpiresAt: f.expires, CredentialExpiresAt: f.credentialExpires}, nil
}

func (f *functionMaterialTransport) start(t *testing.T) *Agent {
	t.Helper()
	agent := f.startUnacquired(t)
	if err := agent.acquire(t.Context()); err != nil {
		t.Fatal(err)
	}
	return agent
}

func (f *functionMaterialTransport) startUnacquired(t *testing.T) *Agent {
	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	done := make(chan error, 1)
	go func() { done <- f.controller.Run(ctx) }()
	t.Cleanup(func() { cancel(); <-done })
	select {
	case <-f.controller.Ready():
	case <-time.After(5 * time.Second):
		t.Fatal("host controller did not subscribe")
	}
	agent, err := NewAgent(AgentConfig{NATSUserPublicKey: testNATSUserKey("function-host"),
		ClockCheck: func() error { return nil }, WorkloadIdentity: testAgentIdentity(),
		Cell: "gru", Node: "function-host", Environment: "production", Roles: []string{"function-worker"},
		Conn: f.conn, Identity: f.hostKey, ControllerPublicKey: f.responseKey.Public().(ed25519.PublicKey),
		Runner: &memoryRunner{observed: make(map[string]Observation)}, InstallRoot: testAgentInstallRoot(t), StateRoot: testAgentStateRoot(t)})
	if err != nil {
		t.Fatal(err)
	}
	return agent
}

func newFunctionMaterialTransport(t *testing.T) *functionMaterialTransport {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("embedded NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	runtime, err := authority.Start(t.Context(), js, authority.Config{Scope: "gru", DeploymentID: entityid.New(), CandidateID: entityid.New(), Replicas: 1})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = runtime.Close() })
	artifacts, err := js.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: "FUNCTION_TRANSPORT_ARTIFACTS", Storage: jetstream.FileStorage})
	if err != nil {
		t.Fatal(err)
	}
	_, responseKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	controller, err := NewController(t.Context(), ControllerConfig{Cell: "gru", Conn: conn, JS: js, Artifacts: artifacts,
		ResponseKey: responseKey, StateReplicas: 1, HostMutations: runtime,
		AuthorityEpoch: func() uint64 { return runtime.Current().Epoch }, AuthorityGuard: runtime.Guard})
	if err != nil {
		t.Fatal(err)
	}
	public, hostKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	registration := Registration{Cell: "gru", Node: "function-host", Environment: "production", Roles: []string{"function-worker"},
		PublicKey: base64.StdEncoding.EncodeToString(public), NATSUserPublicKey: testNATSUserKey("function-host"), Generation: 1}
	if _, err := controller.Register(t.Context(), registration); err != nil {
		t.Fatal(err)
	}
	proof, rootPublic := functionTransportProof(t)
	if _, err := runtime.CommitFunctionIntent(t.Context(), runtime.Current().Epoch, entityid.New(), 0, proof); err != nil {
		t.Fatal(err)
	}
	binding := FunctionMaterialBinding{TaskID: strings.Repeat("a", 25), ServiceID: strings.Repeat("b", 25), NodeID: strings.Repeat("c", 25),
		InstanceID: "ocid1.instance.oc1.sa-saopaulo-1.function", Region: "sa-saopaulo-1",
		HostID: entityid.Derive("host", "gru", "function-host"), Fingerprint: strings.Repeat("d", 64)}
	files := make(map[string][]byte, len(functionMaterialNames))
	for _, name := range functionMaterialNames {
		files[name] = []byte("transport fixture for " + name)
	}
	files["root.pub"], files["module.wasm"], files["receipt.json"], files["delegation.json"] = rootPublic, proof.Module(), proof.Envelope(), proof.Delegation()
	expires := proof.ExpiresAt()
	credentialExpires := expires.Add(30 * time.Minute)
	manifest, err := functionMaterialDigest(files, expires, credentialExpires)
	if err != nil {
		t.Fatal(err)
	}
	grant := authority.FunctionBinding{TaskID: binding.TaskID, ServiceID: binding.ServiceID, NodeID: binding.NodeID,
		InstanceID: binding.InstanceID, Region: binding.Region, HostID: binding.HostID,
		Fingerprint: binding.Fingerprint, MaterialManifestSHA256: manifest}
	if _, err := runtime.CommitFunctionGrant(t.Context(), runtime.Current().Epoch, entityid.New(), 0, proof, grant); err != nil {
		t.Fatal(err)
	}
	return &functionMaterialTransport{controller: controller, conn: conn, authority: runtime, proof: proof,
		binding: binding, grant: grant, files: files, expires: expires, credentialExpires: credentialExpires, hostKey: hostKey, responseKey: responseKey}
}

function_proof.text:
func functionTransportProof(t *testing.T) (release.VerifiedFunction, ed25519.PublicKey) {
	t.Helper()
	module, err := hex.DecodeString("0061736d0100000001040160000003020100070a01065f737461727400000a040102000b")
	if err != nil {
		t.Fatal(err)
	}
	section := append([]byte{0}, bytes.Repeat([]byte{'x'}, 2*artifactChunkBytes)...)
	module = append(module, 0)
	module = binary.AppendUvarint(module, uint64(len(section)))
	module = append(module, section...)
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: entityid.New(),
		FunctionID: "echo", Revision: "first", Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)),
		Environment: "production", Cell: "GRU", Sequence: 42}
	root, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	encodedPublic, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion,
		SubjectKeyID: keyID, SubjectPublicKey: encodedPublic,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}},
	}, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := release.SignFunctionClaim(claim, module, delegation, roots, leaf, now, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	grant, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, grant, module, roots, release.FunctionExpectation{
		Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence}, now)
	if err != nil {
		t.Fatal(err)
	}
	return proof, root
}

session_runtime.text:
func (a *Agent) RunSession(ctx context.Context) error {
	work, cancel := context.WithCancel(ctx)
	defer cancel()
	if err := a.checkClock(); err != nil {
		return err
	}
	if err := a.waitForSession(work); err != nil {
		return err
	}
	lost := make(chan error, 1)
	monitorDone := make(chan struct{})
	go func() {
		defer close(monitorDone)
		a.maintainSessionLease(work, func(reason error) {
			a.sessionFailOnce.Do(func() {
				a.sessionLost.Store(true)
				cancel()
				lost <- reason
			})
		})
	}()
	defer func() { cancel(); <-monitorDone }()
	go a.publishLoad(work)
	go a.publishLogs(work)
	if a.cfg.FollowRollouts != nil {
		go a.cfg.FollowRollouts(work, a)
	}
	if a.cfg.FollowNetBird != nil {
		go a.cfg.FollowNetBird(work, a)
	}
	if a.cfg.Initialized != nil {
		a.cfg.Initialized()
	}
	select {
	case reason := <-lost:
		return reason
	case <-work.Done():
		if a.sessionLost.Load() {
			return <-lost
		}
		return work.Err()
	}
}

session_exchange.text:
func (a *Agent) makeRequest(operation string, payload any) (request, error) {
	data, err := json.Marshal(payload)
	if err != nil {
		return request{}, err
	}
	nonce, err := randomNonce()
	if err != nil {
		return request{}, err
	}
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := request{Version: 1, CredentialProtocol: 1, Node: a.cfg.Node, NATSUserPublicKey: a.cfg.NATSUserPublicKey, Operation: operation, SessionID: a.processID, Epoch: s.Epoch, Nonce: nonce, IssuedAt: time.Now().UTC(), Payload: data}
	if err := signRequest(&r, a.cfg.Identity, a.cfg.Cell); err != nil {
		return request{}, err
	}
	return r, nil
}

// sendToLeader builds, signs and sends a fresh request, and sends a new one
// when a follower controller denies it: every controller of the cell serves
// the host subjects, but only the authority leader answers effectful requests.
// It returns the request whose reply was accepted.
func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

func (a *Agent) acquire(ctx context.Context) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	var s session
	if _, err := a.sendToLeader(ctx, "session", struct {
		Kind string `json:"kind"`
	}{"acquire"}, &s, nil, func(r *request) error {
		r.Epoch = 0
		return signRequest(r, a.cfg.Identity, a.cfg.Cell)
	}); err != nil {
		return fmt.Errorf("acquire host session: %w", err)
	}
	if s.SessionID != a.processID || s.Epoch == 0 {
		return errors.New("invalid acquired host session")
	}
	if err := a.acceptSession(s); err != nil {
		return err
	}
	a.logSessionAccepted("acquire", s)
	return nil
}

func (a *Agent) waitForSession(ctx context.Context) error {
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := a.acquire(ctx); err == nil {
			a.sessionRecovered()
			return nil
		} else if !retrySessionExchange(err) && !errors.Is(err, errSessionOwned) {
			a.logSessionFailure("acquire", err, 0)
			return err
		} else {
			a.logSessionFailure("acquire", err, 0)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

session_lease.text:
func (a *Agent) acceptSession(s session) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	receivedAt := time.Now()
	remaining := s.ExpiresAt.Sub(a.wallTime()) - sessionExecutionReserve
	if remaining <= 0 || remaining > sessionTTL-sessionExecutionReserve+maxClockSkew {
		return errors.New("signed host session has no execution reserve")
	}
	// receivedAt carries Go's monotonic reading. A later wall-clock step cannot
	// extend this locally bounded execution lease.
	deadline := receivedAt.Add(min(remaining, sessionTTL-sessionExecutionReserve))
	a.mu.Lock()
	a.session = s
	a.sessionSafeUntil = deadline
	a.mu.Unlock()
	return nil
}

func (a *Agent) executionLease() (session, time.Time, error) {
	if err := a.checkClock(); err != nil {
		return session{}, time.Time{}, err
	}
	a.mu.RLock()
	s, deadline := a.session, a.sessionSafeUntil
	a.mu.RUnlock()
	if deadline.IsZero() || !time.Now().Before(deadline) || !sessionUsableUntil(s, a.wallTime()) {
		return session{}, time.Time{}, errSessionExecutionReserve
	}
	return s, deadline, nil
}

func (a *Agent) maintainSession(ctx context.Context, cancel context.CancelFunc, lost chan<- error) {
	a.maintainSessionLease(ctx, func(reason error) { a.failSession(cancel, lost, reason) })
}

func (a *Agent) maintainSessionLease(ctx context.Context, fail func(error)) {
	watchCtx, stopWatch := context.WithCancel(ctx)
	watchDone := make(chan struct{})
	go func() {
		defer close(watchDone)
		ticks := a.watchdogTicks
		if ticks == nil {
			ticker := time.NewTicker(time.Second)
			defer ticker.Stop()
			ticks = ticker.C
		}
		for {
			select {
			case <-watchCtx.Done():
				return
			case <-ticks:
				if _, _, err := a.executionLease(); err != nil {
					fail(err)
					return
				}
			}
		}
	}()
	defer func() {
		stopWatch()
		<-watchDone
	}()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		current, deadline, err := a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		current, deadline, err = a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		var next session
		renewCtx, renewCancel := context.WithDeadline(ctx, deadline)
		_, err = a.sendToLeader(renewCtx, "session", struct {
			Kind string `json:"kind"`
		}{"renew"}, &next, nil, nil)
		renewCancel()
		if err == nil {
			if next.SessionID != current.SessionID || next.Epoch != current.Epoch || !next.ExpiresAt.After(current.ExpiresAt) {
				err = errors.New("renewed session binding mismatch")
			} else if _, _, err = a.executionLease(); err == nil {
				if err = a.acceptSession(next); err == nil {
					a.logSessionAccepted("renew", next)
				}
			}
		}
		_, _, leaseErr := a.executionLease()
		if leaseErr != nil {
			fail(leaseErr)
			return
		}
		if err != nil && retrySessionExchange(err) {
			a.logSessionFailure("renew", err, time.Until(deadline))
			continue
		}
		if err != nil {
			a.logSessionFailure("renew", err, time.Until(deadline))
			fail(fmt.Errorf("host session renewal failed: %w", err))
			return
		}
		a.sessionRecovered()
	}

wire_exchange.text:
func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}

controller_nats.text:
func (c *Controller) Run(ctx context.Context) error {
	var subscriptions []*nats.Subscription
	unsubscribe := func() {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		subscriptions = nil
	}
	defer func() {
		unsubscribe()
		c.closeCache()
	}()
	ticker := time.NewTicker(hostLeaderPoll)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		leader := c.authorityLeader == nil || c.authorityLeader()
		if leader && subscriptions == nil {
			var err error
			if subscriptions, err = c.subscribeHostRequests(ctx); err != nil {
				return err
			}
		} else if !leader && subscriptions != nil {
			unsubscribe()
		}
		c.readyOnce.Do(func() { close(c.ready) })
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func (c *Controller) subscribeHostRequests(ctx context.Context) ([]*nats.Subscription, error) {
	subscriptions := make([]*nats.Subscription, 0, len(hostOperations))
	for _, operation := range hostOperations {
		sub, err := c.conn.QueueSubscribe(protocol.AgentObservation(c.cell, "*", operation), "host-controller-"+operation, func(msg *nats.Msg) { c.handle(ctx, msg) })
		if err == nil {
			subscriptions = append(subscriptions, sub)
			continue
		}
		for _, existing := range subscriptions {
			_ = existing.Unsubscribe()
		}
		return nil, err
	}
	flushCtx, flushCancel := context.WithTimeout(ctx, 5*time.Second)
	err := c.conn.FlushWithContext(flushCtx)
	flushCancel()
	if err != nil {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		return nil, fmt.Errorf("flush host subscriptions: %w", err)
	}
	return subscriptions, nil
}

controller_store.text:
func NewController(ctx context.Context, cfg ControllerConfig) (*Controller, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.Conn == nil || cfg.JS == nil || cfg.Artifacts == nil || cfg.HostMutations == nil || len(cfg.ResponseKey) != ed25519.PrivateKeySize {
		return nil, errors.New("controller requires NATS, JetStream, ordered host mutations, artifact store and Ed25519 response key")
	}
	if cfg.AuthorityEpoch == nil || cfg.AuthorityGuard == nil {
		return nil, errors.New("controller requires authority epoch and guard")
	}
	managedEffectGate := cfg.ManagedEffectGate
	if managedEffectGate == nil {
		if gate, ok := cfg.HostMutations.(interface {
			BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
		}); ok {
			managedEffectGate = gate.BeginActiveWorkloadEffect
		}
	}
	if cfg.ManagedRegistrationVerifier != nil && managedEffectGate == nil {
		return nil, errors.New("managed host registration requires a terminal effect gate")
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("invalid host state replica count")
	}
	state := cfg.State
	if state == nil {
		var err error
		state, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: stateBucket, History: 2, MaxValueSize: 64 << 10, MaxBytes: 256 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
		if err != nil {
			return nil, fmt.Errorf("open host state: %w", err)
		}
	}
	status, err := state.Status(ctx)
	if err != nil {
		if cfg.State == nil && errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect host state: %w", ErrStateNotReady, err)
		}
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	if err := rejectObsoleteRetirementState(ctx, state, cfg.Cell); err != nil {
		return nil, err
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, fmt.Errorf("open ordered control log: %w", err)
		}
	}
	cacheCtx, cacheCancel := context.WithCancel(context.Background())
	return &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations,
		managedVerifier: cfg.ManagedRegistrationVerifier, managedDesiredVerifier: cfg.ManagedDesiredVerifier,
		managedEffectGate: managedEffectGate, materialProvider: cfg.ManagedMaterialProvider,
		credentialFloor: cfg.ManagedCredentialFloor, volumeInspector: cfg.ManagedVolumeInspector, runtimeEffects: cfg.RuntimeEffects,
		containerMaterial: cfg.ContainerMaterialProvider, registryAdmission: cfg.RegistryAdmissionProvider,
		taskLoadRoles:    cfg.TaskLoadRoles,
		functionMaterial: cfg.FunctionMaterialProvider,
		terraBaseCA:      cfg.TerraBaseCA, roleIdentity: cfg.RoleIdentity, nodeAddress: cfg.NodeAddress, restartGate: cfg.RestartGate, artifacts: cfg.Artifacts, responseKey: cfg.ResponseKey, ready: make(chan struct{}),
		authorityEpoch: cfg.AuthorityEpoch, authorityGuard: cfg.AuthorityGuard, authorityLeader: cfg.AuthorityLeader,
		cacheContext: cacheCtx, cacheCancel: cacheCancel}, nil
}

