// failingRunner observes and stops a member like memoryRunner, failing on
// request.
type failingRunner struct {
	*memoryRunner
	observeErr, stopErr error
	stops               int
}

func (r *failingRunner) Observe(ctx context.Context, role string) (Observation, error) {
	if r.observeErr != nil {
		return Observation{}, r.observeErr
	}
	return r.memoryRunner.Observe(ctx, role)
}

func (r *failingRunner) Stop(ctx context.Context, role string) error {
	r.stops++
	if r.stopErr != nil {
		return r.stopErr
	}
	return r.memoryRunner.Stop(ctx, role)
}

volume_fence.text:
func (a *Agent) ensureTerraBaseDataVolume(ctx context.Context) error {
	if err := a.establishTerraBaseDataVolume(ctx); err != nil {
		a.terraBaseVolumeConfirmed = ""
		return err
	}
	uuid, err := dataFilesystemUUID()
	if err != nil || uuid == a.terraBaseVolumeConfirmed {
		return err
	}
	// A filesystem not yet confirmed is recorded, or checked against the
	// record: an adopted volume spends the member's first format too, and
	// another filesystem on the device is refused.
	a.terraBaseVolumeConfirmed = ""
	recorded, err := confirmDataFilesystem(ctx, a, uuid)
	if err != nil {
		return err
	}
	if recorded != uuid {
		return fmt.Errorf("data volume holds ext4 %s, but member %s was initialized with %s; attach the member's own volume or restore it",
			uuid, a.cfg.Node, recorded)
	}
	a.terraBaseVolumeConfirmed = uuid
	return nil
}

// terraBaseDataVolumeIntact checks locally, without repairing anything, that
// the member data directory is the verified mount of the filesystem the
// controller confirmed.
func (a *Agent) terraBaseDataVolumeIntact() error {
	if err := verifyDataMount(terrabase.Layout(a.cfg.TerraBaseRoot).Data(), a.cfg.WorkloadIdentity); err != nil {
		return err
	}
	uuid, err := dataFilesystemUUID()
	if err != nil {
		return err
	}
	if a.terraBaseVolumeConfirmed == "" || uuid != a.terraBaseVolumeConfirmed {
		return fmt.Errorf("data volume holds ext4 %s, not the confirmed %q", uuid, a.terraBaseVolumeConfirmed)
	}
	return nil
}

// fenceTerraBaseMember stops the member when its data volume is not intact,
// before anything tries to repair the mount. It checks the volume first and
// stops whenever the runner cannot show that the member is stopped. stopped
// reports a member it stopped; an error means a writer may still run, and
// the caller must not go on to repair the mount.
func (a *Agent) fenceTerraBaseMember(ctx context.Context, role string) (stopped bool, err error) {
	if !a.cfg.TerraBaseDataVolume || role != terrabase.Role {
		return false, nil
	}
	lost := a.terraBaseDataVolumeIntact()
	if lost == nil {
		return false, nil
	}
	a.terraBaseVolumeConfirmed = ""
	current, observeErr := a.runner.Observe(ctx, role)
	if observeErr == nil && !current.Running {
		return false, nil
	}
	if err := a.runner.Stop(ctx, role); err != nil {
		return false, errors.Join(fmt.Errorf("stop the terrabase member: data volume: %w", lost), observeErr, err)
	}
	delete(a.terraBase, role)
	slog.WarnContext(ctx, "terrabase member stopped: its data volume is not intact", "error", lost)
	return true, nil
}

volume_request.text:
func (a *Agent) establishTerraBaseDataVolume(ctx context.Context) error {
	data := terrabase.Layout(a.cfg.TerraBaseRoot).Data()
	if verifyDataMount(data, a.cfg.WorkloadIdentity) == nil {
		if time.Since(a.terraBaseVolumeChecked) < terraBaseVolumeRecheck {
			return nil
		}
		// The mount is in place, so maintenance is best effort, and bounded:
		// the member is fenced again only after it returns.
		a.terraBaseVolumeChecked = time.Now()
		maintenance, cancel := context.WithTimeout(ctx, terraBaseMaintenanceTimeout)
		defer cancel()
		if err := requestTerraBaseDataVolume(maintenance, a.cfg.VolumeInitSocket, nil); err != nil {
			slog.WarnContext(maintenance, "terrabase data volume maintenance failed", "error", err)
		}
		return verifyDataMount(data, a.cfg.WorkloadIdentity)
	}
	err := requestTerraBaseDataVolume(ctx, a.cfg.VolumeInitSocket, nil)
	if needed, ok := errors.AsType[terraBaseFormatNeeded](err); ok {
		// Retry the same durable initializer attempt; issuing a response does
		// not consume it. The helper consumes it durably immediately before mkfs.
		var reply terraBaseFormatReply
		var grant protocol.Envelope
		if _, err = a.sendToLeader(ctx, "terrabase-format", terraBaseFormatQuery{VolumeID: a.cfg.TerraBaseDataVolumeID, AttemptID: needed.AttemptID}, &reply, &grant, nil); err == nil {
			err = requestTerraBaseDataVolume(ctx, a.cfg.VolumeInitSocket, &grant)
		}
	}
	if err != nil {
		return fmt.Errorf("terrabase data volume is not mounted: %w", err)
	}
	if err := verifyDataMount(data, a.cfg.WorkloadIdentity); err != nil {
		return fmt.Errorf("terrabase data volume mount readback: %w", err)
	}
	a.terraBaseVolumeChecked = time.Now()
	return nil
}

func requestTerraBaseDataVolume(ctx context.Context, socket string, grant *protocol.Envelope) error {
	wire := terraBaseDataRequest
	if grant != nil {
		encoded, err := protocol.EncodeJSON(*grant)
		if err != nil {
			return err
		}
		wire = slices.Concat(terraBaseDataRequest, []byte("\n"), encoded)
	}
	if socket == "" {
		socket = volumeInitSocketPath
	}
	connection, err := (&net.Dialer{Timeout: 5 * time.Second}).DialContext(ctx, "unix", socket)
	if err != nil {
		return fmt.Errorf("connect fixed volume initializer: %w", err)
	}
	defer connection.Close()
	stop := context.AfterFunc(ctx, func() { _ = connection.Close() })
	defer stop()
	// The first mount may format the whole volume.
	if err := connection.SetDeadline(time.Now().Add(20 * time.Minute)); err != nil {
		return err
	}
	if err := exchangeVolumeInit(connection, wire); err != nil {
		if errors.Is(err, errFormatGrantNeeded) {
			return err
		}
		return fmt.Errorf("volume initializer did not mount %s; its journal has the cause: %w", oci.MemberVolumeDevice, err)
	}
	return nil
}

volume_exchange.text:
func exchangeVolumeInit(connection net.Conn, wire []byte) error {
	var size [4]byte
	binary.BigEndian.PutUint32(size[:], uint32(len(wire)))
	if _, err := connection.Write(size[:]); err != nil {
		return err
	}
	if _, err := connection.Write(wire); err != nil {
		return err
	}
	var result [1]byte
	if _, err := io.ReadFull(connection, result[:]); err != nil {
		return err
	}
	switch result[0] {
	case 0:
		return nil
	case volumeInitNeedsGrant:
		var attempt [26]byte
		if _, err := io.ReadFull(connection, attempt[:]); err != nil {
			return err
		}
		if !entityid.Valid(string(attempt[:])) {
			return errors.New("volume initializer returned an invalid first-format attempt")
		}
		return terraBaseFormatNeeded{AttemptID: string(attempt[:])}
	}
	return errors.New("volume initializer refused the request")
}

reconcile.text:
func (a *Agent) reconcile(ctx context.Context, role string) (resultErr error) {
	if a.sessionLost.Load() {
		return errors.New("host session was lost")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	if _, err := a.fenceTerraBaseMember(ctx, role); err != nil {
		return err
	}
	pending, hasPending := a.pending[role]
	if hasPending && pending.outcomeReady {
		if err := a.flushCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	var target desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if err := a.validateDesiredReply(target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if target.Desired == nil {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if hasPending {
			if err := a.failPendingCycle(ctx, role); err != nil {
				return err
			}
		}
		return nil
	}
	d := *target.Desired
	if d.Cell != a.cfg.Cell || d.Node != a.cfg.Node || d.Environment != a.cfg.Environment || d.Role != role || d.Generation == 0 {
		return errors.Join(errors.New("desired identity mismatch"), a.revokeManagedNativeRoot(role))
	}
	if err := validateDesired(d, a.cfg.Cell, *target.Registration); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if !d.Withdrawn && d.ManagedMember != nil {
		fingerprint, err := desiredFingerprint(d)
		if err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.pinManagedNativeRootDesired(role, fingerprint); err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.stopManagedNativeRootIfChanged(role, fingerprint); err != nil {
			return err
		}
	}
	if hasPending && (d.Withdrawn || d.Generation != pending.query.Generation || d.Digest != pending.query.Digest || d.AuthorityEpoch != pending.query.AuthorityEpoch) {
		if err := a.failPendingCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	backupObserved := false
	defer func() {
		if resultErr != nil && !backupObserved && !errors.Is(resultErr, errSessionContention) {
			_ = a.publishReport(ctx, a.reportFor(d, "failed", resultErr))
		}
	}()
	if d.Withdrawn {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if err := a.runner.Stop(ctx, role); err != nil {
			return err
		}
		return a.publishReport(ctx, a.reportFor(d, "stopped", nil))
	}
	if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if d.ManagedMember != nil {
		if d.ManagedMember.Runtime != nil && a.cfg.ManagedRuntimeRoot != "" {
			backup, err := a.fetchManagedBackupCommand(ctx, role)
			if err != nil {
				return err
			}
			if backup.Pending {
				current, err := a.runner.Observe(ctx, role)
				if err != nil {
					return err
				}
				if !current.Running {
					err := a.reconcileManaged(ctx, d, target, true)
					backupObserved = err == nil
					return err
				}
				var operationErr error
				if backup.Command != nil {
					operationErr = a.reconcileManagedBackup(ctx, d, *target.Registration, *backup.Command)
				}
				reportErr := a.reportManagedBackupProcess(ctx, d, nil)
				backupObserved = reportErr == nil
				return errors.Join(operationErr, reportErr)
			}
			command, err := a.fetchManagedDrainCommand(ctx, role)
			if err != nil {
				return err
			}
			if command != nil {
				return a.reconcileManagedDrain(ctx, d, *target.Registration, *command)
			}
		}
		return a.reconcileManaged(ctx, d, target, false)
	}
	if err := a.revokeManagedNativeRoot(role); err != nil {
		return err
	}
	fingerprint, err := desiredFingerprint(d)
	if err != nil {
		return err
	}
	current, err := a.runner.Observe(ctx, role)
	if err != nil {
		return err
	}
	if (a.terraBaseMember(d) || a.tsAuthReplica(d)) && a.terraBaseExited(current, d, fingerprint) {
		return errors.New(role + " exited; it is relaunched on the next poll")
	}
	// A running workload renews its identity on every pass, held or not, so
	// it cannot expire while a release waits behind a restart hold (TS-803).
	var filesErr error
	if current.Running {
		filesErr = a.refreshRoleFiles(ctx, d)
	}
	if current.Running && current.Digest == d.Digest && current.Fingerprint == fingerprint {
		if hasPending {
			pending.query.Succeeded = true
			pending.outcomeReady = true
			a.pending[role] = pending
			if err := a.flushCycle(ctx, role); err != nil {
				return err
			}
		}
		report := a.reportFor(d, "running", nil)
		if a.terraBaseMember(d) {
			report = a.terraBaseRunningReport(ctx, d)
		} else if a.tsAuthReplica(d) {
			report = a.tsAuthRunningReport(ctx, d)
		}
		if filesErr != nil {
			report.Error = strings.TrimPrefix(report.Error+"; "+filesErr.Error(), "; ")
		}
		return a.publishReport(ctx, report)
	}
	var query cycleQuery
	var cycle cycleReply
	if hasPending {
		query = pending.query
		cycle = cycleReply{CycleID: query.CycleID, Fence: query.Fence, State: "active"}
	} else {
		if current.Running && a.restartHeld(d) {
			return a.publishReport(ctx, a.reportFor(d, "waiting", filesErr))
		}
		attempt, err := randomID()
		if err != nil {
			return err
		}
		query = cycleQuery{Role: role, Digest: d.Digest, Generation: d.Generation, AuthorityEpoch: d.AuthorityEpoch, Attempt: attempt}
		if err := a.request(ctx, "cycle", query, &cycle); err != nil {
			return err
		}
		if cycle.State == "held" {
			// The running workload keeps serving until the controller
			// grants the restart (a TerraBase seat waits for its drain).
			return a.publishReport(ctx, a.reportFor(d, "waiting", filesErr))
		}
		if cycle.State != "active" {
			return nil
		}
		query.CycleID = cycle.CycleID
		query.Fence = cycle.Fence
		a.pending[role] = pendingCycle{query: query}
	}
	cycleSucceeded := false
	defer func() {
		if resultErr != nil && !cycleSucceeded && !errors.Is(resultErr, errSessionContention) {
			pending := a.pending[role]
			pending.query.Succeeded = false
			pending.outcomeReady = true
			a.pending[role] = pending
			if ctx.Err() != nil || a.sessionLost.Load() {
				return
			}
			finishCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			_ = a.flushCycle(finishCtx, role)
		}
	}()
	executable, err := a.fetchArtifact(ctx, role, d.Digest)
	if err != nil {
		return err
	}
	workload := Workload{Role: role, Digest: d.Digest, Fingerprint: fingerprint, Executable: executable, Args: d.Args, Env: d.Env,
		CgroupMemoryMaxBytes: a.cfg.RoleMemoryMaxBytes[role]}
	if a.tsAuthMisplaced(d) {
		return errors.New("ts-auth needs ts_auth_root on this host for its bundle directory and readiness probe")
	}
	secrets, err := a.resolveSecrets(ctx, d)
	if err != nil {
		return err
	}
	roleEnv, err := a.prepareRoleFiles(ctx, d, secrets)
	if err != nil {
		return err
	}
	if len(secrets) != 0 {
		workload.Env = maps.Clone(d.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, secrets)
	}
	started, certificateExpiry := "running", time.Time{}
	if a.terraBaseMember(d) {
		if workload.Env, certificateExpiry, err = a.prepareTerraBase(ctx, d); err != nil {
			return err
		}
		workload.DrainTimeout, started = terraBaseDrain, "starting"
	}
	if a.tsAuthReplica(d) {
		if workload.Env, err = a.prepareTSAuth(d, secrets); err != nil {
			return err
		}
		workload.DrainTimeout, started = tsAuthDrain, "starting"
	}
	if len(roleEnv) != 0 {
		workload.Env = maps.Clone(workload.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, roleEnv)
	}
	var latest desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &latest); err != nil {
		return err
	}
	if err := a.validateDesiredReply(latest); err != nil {
		return err
	}
	if !sameDesiredReplyBinding(target, latest) {
		return errors.New("desired target changed before native apply")
	}
	var active cycleReply
	if err := a.request(ctx, "cycle", cycleQuery{Role: role, Digest: d.Digest, Generation: d.Generation, AuthorityEpoch: d.AuthorityEpoch, Attempt: query.Attempt}, &active); err != nil {
		return err
	}
	if active.State != "active" || active.CycleID != cycle.CycleID || active.Fence != cycle.Fence {
		return errors.New("cycle fence changed before native apply")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	// The controller requests above took time: launch only on the
	// confirmed filesystem's mount as it is now.
	if a.terraBaseMember(d) && a.cfg.TerraBaseDataVolume {
		if err := a.terraBaseDataVolumeIntact(); err != nil {
			a.terraBaseVolumeConfirmed = ""
			return fmt.Errorf("terrabase data volume changed before launch: %w", err)
		}
	}
	if err := a.runner.Apply(ctx, workload); err != nil {
		return err
	}
	if !certificateExpiry.IsZero() {
		a.terraBase[role] = terraBaseMember{certificateExpiry: certificateExpiry}
	}
	observed, err := a.runner.Observe(ctx, role)
	if err != nil {
		return err
	}
	if !observed.Running || observed.Digest != d.Digest || observed.Fingerprint != fingerprint {
		return errors.New("native workload did not start")
	}
	cycleSucceeded = true
	pending = a.pending[role]
	pending.query.Succeeded = true
	pending.outcomeReady = true
	a.pending[role] = pending
	if err := a.flushCycle(ctx, role); err != nil {
		return err
	}
	if err := a.publishReport(ctx, a.reportFor(d, started, nil)); err != nil {
		return err
	}
	return nil
}

artifact_fetch.text:
func (a *Agent) fetchArtifact(ctx context.Context, role, digest string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
	defer cancel()
	root := filepath.Join(a.cfg.InstallRoot, role, "sha256-"+digest)
	path := filepath.Join(root, role)
	for _, directory := range []string{a.cfg.InstallRoot, filepath.Join(a.cfg.InstallRoot, role), root} {
		if err := ensureInstallDirectory(directory, a.cfg.WorkloadIdentity.GID); err != nil {
			return "", err
		}
	}
	if valid, err := verifyInstalledArtifact(path, digest, a.cfg.WorkloadIdentity.GID); err != nil {
		return "", err
	} else if valid {
		return path, nil
	}
	tmp, err := os.CreateTemp(root, "partial-*")
	if err != nil {
		return "", err
	}
	defer os.Remove(tmp.Name())
	defer tmp.Close()
	hash := sha256.New()
	var offset, total int64
	for {
		ctx := observability.StartTrace(ctx)
		var part artifactReply
		if err := a.request(ctx, "artifact", artifactQuery{Role: role, Digest: digest, Offset: offset, Length: artifactChunkBytes}, &part); err != nil {
			if errors.Is(err, errArtifactPreparing) || errors.Is(err, errSessionContention) {
				select {
				case <-ctx.Done():
					return "", ctx.Err()
				case <-time.After(250 * time.Millisecond):
					continue
				}
			}
			return "", err
		}
		if part.Digest != digest || part.Offset != offset || part.Total <= 0 || part.Total > maxArtifactBytes || len(part.Data) == 0 || len(part.Data) > artifactChunkBytes || offset+int64(len(part.Data)) > part.Total || total != 0 && part.Total != total {
			return "", errors.New("artifact chunk binding mismatch")
		}
		total = part.Total
		if _, err := tmp.Write(part.Data); err != nil {
			return "", err
		}
		if _, err := hash.Write(part.Data); err != nil {
			return "", err
		}
		offset += int64(len(part.Data))
		if offset == total {
			break
		}
	}
	if hex.EncodeToString(hash.Sum(nil)) != digest {
		return "", errors.New("artifact SHA-256 mismatch")
	}
	if err := tmp.Chown(-1, int(a.cfg.WorkloadIdentity.GID)); err != nil {
		return "", err
	}
	if err := tmp.Chmod(0550); err != nil {
		return "", err
	}
	if err := tmp.Sync(); err != nil {
		return "", err
	}
	if err := tmp.Close(); err != nil {
		return "", err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return "", err
	}
	dir, err := os.Open(root)
	if err != nil {
		return "", err
	}
	defer dir.Close()
	if err := dir.Sync(); err != nil {

artifact_serve.text:
func (c *Controller) serveArtifact(ctx context.Context, req request, r Registration) (any, error) {
	var query artifactQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(r.Roles, query.Role) || validateDigest(query.Digest) != nil || query.Offset < 0 || query.Length < 1 || query.Length > artifactChunkBytes {
		return nil, errors.New("invalid artifact query")
	}
	d, _, exists, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil {
		return nil, err
	}
	if !exists || d.Withdrawn || d.Digest != query.Digest {
		return nil, errors.New("artifact is not desired for this host")
	}
	data, total, err := c.readArtifactChunk(ctx, query.Digest, query.Offset, query.Length)
	if err != nil {
		return nil, err
	}
	current, _, exists, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil {
		return nil, err
	}
	if !exists || current.Withdrawn || current.Digest != query.Digest || current.Generation != d.Generation || current.AuthorityEpoch != d.AuthorityEpoch {
		return nil, errors.New("artifact target changed")
	}
	if _, _, err := c.authorize(ctx, req); err != nil {
		return nil, err
	}
	return artifactReply{Digest: query.Digest, Offset: query.Offset, Total: total, Data: data}, nil
}

artifact_cache.text:
func (c *Controller) readArtifactChunk(ctx context.Context, digest string, offset int64, length int) ([]byte, int64, error) {
	return c.readCachedArtifact(ctx, &c.workloadCache, maxArtifactBytes, digest, offset, length)
}

func (c *Controller) readCachedArtifact(ctx context.Context, cache *artifactCache, maxBytes int64, digest string, offset int64, length int) ([]byte, int64, error) {
	if err := ctx.Err(); err != nil {
		return nil, 0, err
	}
	c.cacheMu.Lock()
	defer c.cacheMu.Unlock()
	if c.cacheClosed {
		return nil, 0, errors.New("artifact cache is closed")
	}
	if cache.digest != digest || cache.file == nil {
		if !cache.downloading && !time.Now().Before(cache.retryAfter) {
			cache.downloading = true
			go c.downloadArtifact(cache, maxBytes, digest)
		}
		return nil, 0, errArtifactPreparing
	}
	if offset < 0 || offset >= cache.size {
		return nil, 0, errors.New("artifact offset is outside object")
	}
	count := min(int64(length), cache.size-offset)
	data := make([]byte, count)
	if _, err := cache.file.ReadAt(data, offset); err != nil {
		return nil, 0, err
	}
	return data, cache.size, nil
}

func (c *Controller) downloadArtifact(cache *artifactCache, maxBytes int64, digest string) {
	ctx, cancel := context.WithTimeout(c.cacheContext, 2*time.Minute)
	defer cancel()
	var downloaded *os.File
	var size int64
	var fetchErr error
	defer func() {
		c.cacheMu.Lock()
		defer c.cacheMu.Unlock()
		cache.downloading = false
		if c.cacheClosed || fetchErr != nil {
			if downloaded != nil {
				_ = downloaded.Close()
			}
			if fetchErr != nil {
				cache.retryAfter = time.Now().Add(3 * time.Second)
			}
			return
		}
		if cache.file != nil {
			_ = cache.file.Close()
		}
		cache.file = downloaded
		cache.digest = digest
		cache.size = size
	}()
	info, err := c.artifacts.GetInfo(ctx, "sha256-"+digest)
	if err != nil {
		fetchErr = err
		return
	}
	if info == nil || info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > uint64(maxBytes) {
		fetchErr = errors.New("artifact metadata is invalid")
		return
	}
	js, err := jetstream.New(c.conn)
	if err != nil {
		fetchErr = err
		return
	}
	file, err := os.CreateTemp("", "ts-host-artifact-*")
	if err != nil {
		fetchErr = err
		return
	}
	_ = os.Remove(file.Name())
	downloaded = file
	if err := artifact.ReadVerified(ctx, js, c.artifacts, info.Bucket, "sha256-"+digest,
		digest, int64(info.Size), maxBytes, file); err != nil {
		fetchErr = err
		return
	}
	if err := file.Sync(); err != nil {
		fetchErr = err
		return
	}
	size = int64(info.Size)
}

role_prepare.text:
func (a *Agent) prepareRoleFiles(ctx context.Context, d Desired, secrets map[string]string) (map[string]string, error) {
	files := map[string]string{}
	for key, value := range secrets {
		if vaultsecret.FileKey(key) {
			files[key] = value
			delete(secrets, key)
		}
	}
	grant, granted := roleidentity.Grants[d.Role]
	if len(files) == 0 && (!granted || a.cfg.ManagedRuntimeRoot == "") {
		return nil, nil
	}
	dir, err := a.ensureRoleDir(d.Role)
	if err != nil {
		return nil, err
	}
	env := map[string]string{}
	if err := a.writeSecretFiles(dir, files); err != nil {
		return nil, err
	}
	for key := range files {
		env[key] = filepath.Join(dir, strings.ToLower(key))
	}
	if granted {
		_ = a.ensureRoleIdentity(ctx, d.Role, dir)
		if _, current := roleIdentityExpiry(dir); current {
			env[grant.EnvPrefix+"URL"] = a.cfg.NATSURL
			env[grant.EnvPrefix+"CREDENTIALS_FILE"] = filepath.Join(dir, "nats.creds")
			env[grant.EnvPrefix+"CERTIFICATE"] = filepath.Join(dir, "nats.pem")
			env[grant.EnvPrefix+"PRIVATE_KEY"] = filepath.Join(dir, "nats.key")
			env[grant.EnvPrefix+"CA"] = filepath.Join(dir, "nats-ca.pem")
		}
	}
	return env, nil
}

// roleFilesRetry is how long a member waits after a failed renewal.
const roleFilesRetry = time.Minute

type roleFilesFailure struct {
	at  time.Time
	err error
}

// refreshRoleFiles renews a running member's files when they are due: its
// secret files each minute and its NATS identity at half its lifetime. After a
// failure it reports the same error for a minute before it tries again.
func (a *Agent) refreshRoleFiles(ctx context.Context, d Desired) error {
	fileRefs := maps.Clone(d.Secrets)
	maps.DeleteFunc(fileRefs, func(key string, _ vaultsecret.Ref) bool { return !vaultsecret.FileKey(key) })
	_, granted := roleidentity.Grants[d.Role]
	if len(fileRefs) == 0 && (!granted || a.cfg.ManagedRuntimeRoot == "") {
		return nil

terrabase_prepare.text:
func (a *Agent) prepareTerraBase(ctx context.Context, d Desired) (map[string]string, time.Time, error) {
	if len(d.Args) != 0 {
		// The binary lets an argument override the host-owned settings.
		return nil, time.Time{}, errors.New("terrabase members take no arguments")
	}
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return nil, time.Time{}, err
	}
	peer, listed := a.terraBasePeer(profile)
	if !listed {
		return nil, time.Time{}, fmt.Errorf("node %s is not in %s", a.cfg.Node, terrabase.EnvPeers)
	}
	// Recheck the ancestors right before the privileged effects below.
	if err := validateTerraBaseRoot(a.cfg.TerraBaseRoot, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.WorkloadIdentity); err != nil {
		return nil, time.Time{}, err
	}
	layout := terrabase.Layout(a.cfg.TerraBaseRoot)
	supervisor, uid, gid := os.Geteuid(), int(a.cfg.WorkloadIdentity.UID), int(a.cfg.WorkloadIdentity.GID)
	// The binary writes its databases and extracted libraries; it only
	// reads its TLS material, which stays supervisor-owned.
	type ownedDir struct {
		path     string
		uid, gid int
		mode     os.FileMode
	}
	dirs := []ownedDir{{string(layout), supervisor, gid, 0o750}, {layout.TLS(), supervisor, gid, 0o750},
		{layout.Bundle(), uid, gid, 0o700}}
	if !a.cfg.TerraBaseDataVolume {
		dirs = append(dirs, ownedDir{layout.Data(), uid, gid, 0o700})
	}
	for _, dir := range dirs {
		if err := ensureOwnedDir(dir.path, dir.uid, dir.gid, dir.mode); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The volume initializer owns a data volume mount; never fall back to
	// the boot disk without one.
	if a.cfg.TerraBaseDataVolume {
		// Artifact and controller requests may have outlasted the caller's
		// fence. Stop any remaining writer before repairing a lost mount.
		if _, err := a.fenceTerraBaseMember(ctx, d.Role); err != nil {
			return nil, time.Time{}, err
		}
		if err := a.ensureTerraBaseDataVolume(ctx); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The member's private key never reaches disk (TS-745).
	if a.cfg.MemoryRuntime {
		if err := vaultsecret.RequireMemoryFilesystem(layout.TLS()); err != nil {
			return nil, time.Time{}, err
		}
	}
	key, err := os.ReadFile(layout.Key())
	if errors.Is(err, os.ErrNotExist) {
		if key, _, err = terrabase.NewMemberKey(); err == nil {
			err = writeOwnedFile(layout.Key(), key, gid)
		}
	}
	if err != nil {
		return nil, time.Time{}, err
	}
	certificate, _ := os.ReadFile(layout.Certificate())
	ca, _ := os.ReadFile(layout.CA())
	if !terrabase.CurrentCertificate(certificate, key, ca, peer, time.Now()) {
		csr, err := terrabase.CertificateRequest(key)
		if err != nil {
			return nil, time.Time{}, err
		}
		var reply terraBasePeerReply
		if err := a.request(ctx, "terrabase-peer", terraBasePeerQuery{CSR: csr}, &reply); err != nil {
			return nil, time.Time{}, err
		}
		if !terrabase.CurrentCertificate(reply.Certificate, key, reply.CA, peer, time.Now()) {
			return nil, time.Time{}, errors.New("controller returned an unusable TerraBase member certificate")
		}
		if err := writeOwnedFile(layout.CA(), reply.CA, gid); err != nil {
			return nil, time.Time{}, err
		}
		if err := writeOwnedFile(layout.Certificate(), reply.Certificate, gid); err != nil {
			return nil, time.Time{}, err
		}
		certificate = reply.Certificate
	}
	return layout.Env(d.Env, profile, peer.Name), terrabase.CertificateExpiry(certificate), nil
}

authority_runtime.text:
func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

authority_commit.text:
func (r *Runtime) CommitHostMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	if kind == MutationUsageObservation {
		return 0, errors.New("usage observations require verified host authority")
	}
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	return r.commitMutation(ctx, expectedEpoch, kind, subjectKey, operationID, expectedSubjectSequence, payload)
}

func (r *Runtime) CommitHostMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	if verify == nil {
		return 0, errors.New("verified host mutation requires a verifier")
	}
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, verify)
}

func (r *Runtime) commitMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, nil)
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

authority_read.text:
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

authority_function.text:
func (r *Runtime) CommitFunctionIntent(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction,
) (uint64, error) {
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	intent := FunctionIntent{Claim: proof.Claim(), EnvelopeSHA256: proof.EnvelopeSHA256(),
		Envelope: proof.Envelope(), Delegation: proof.Delegation()}
	key, err := functionIntentKey(intent.Claim.TenantID, intent.Claim.FunctionID)
	if err != nil {
		return 0, err
	}
	if r == nil || strings.ToLower(intent.Claim.Cell) != r.config.Scope {
		return 0, release.ErrExpectationMismatch
	}
	payload, err := json.Marshal(intent, json.FormatNilSliceAsNull(true))
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionIntent, key, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if !proof.Valid() {
				return trust.ErrExpired
			}
			prior, err := r.ReadFunctionIntent(ctx, intent.Claim.TenantID, intent.Claim.FunctionID)
			if !proof.Valid() {
				return trust.ErrExpired
			}
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			current, err := DecodeFunctionIntent(prior)
			if err != nil {
				return err
			}
			if intent.Claim.Sequence < current.Claim.Sequence ||
				intent.Claim.Sequence == current.Claim.Sequence && !bytes.Equal(payload, prior.Payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionIntent(ctx context.Context, tenantID, functionID string) (LogEntry, error) {
	key, err := functionIntentKey(tenantID, functionID)
	if err != nil {
		return LogEntry{}, err
	}
	return r.ReadHostMutation(ctx, MutationFunctionIntent, key)
}

func (r *Reader) ReadFunctionIntent(ctx context.Context, tenantID, functionID string) (LogEntry, error) {
	key, err := functionIntentKey(tenantID, functionID)
	if err != nil {
		return LogEntry{}, err
	}
	return r.ReadHostMutation(ctx, MutationFunctionIntent, key)
}

func DecodeFunctionIntent(entry LogEntry) (FunctionIntent, error) {
	var intent FunctionIntent
	if err := json.Unmarshal(entry.Payload, &intent, json.RejectUnknownMembers(true)); err != nil {
		return intent, err
	}
	key, err := functionIntentKey(intent.Claim.TenantID, intent.Claim.FunctionID)
	if err != nil || entry.Kind != MutationFunctionIntent || entry.SubjectKey != key || entry.Sequence == 0 {
		return FunctionIntent{}, errors.New("function intent control-log identity is invalid")
	}
	if err := intent.Claim.Validate(); err != nil {
		return FunctionIntent{}, err
	}
	envelope, err := trust.DecodeEnvelope(intent.Envelope)
	if err != nil {
		return FunctionIntent{}, err
	}
	claim, err := trust.EncodePayload(intent.Claim)
	if err != nil {
		return FunctionIntent{}, err
	}
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil || fingerprint != intent.EnvelopeSHA256 || !bytes.Equal(claim, envelope.Payload) ||
		envelope.Scope != release.FunctionScope(intent.Claim) {
		return FunctionIntent{}, errors.New("function intent does not match its signed envelope")
	}
	if _, err := trust.DecodeEnvelope(intent.Delegation); err != nil {
		return FunctionIntent{}, err
	}
	return intent, nil
}

// VerifyFunctionIntent compares an already verified, still-current signature
// against the durable floor. Readers must separately verify retained wire with
// their trusted roots and module bytes before producing a sealed proof.
func (r *Runtime) VerifyFunctionIntent(ctx context.Context, proof release.VerifiedFunction) error {
	return verifyFunctionIntent(ctx, r, proof)
}

func (r *Reader) VerifyFunctionIntent(ctx context.Context, proof release.VerifiedFunction) error {
	return verifyFunctionIntent(ctx, r, proof)
}

type functionIntentReader interface {
	ReadFunctionIntent(context.Context, string, string) (LogEntry, error)
}

func verifyFunctionIntent(ctx context.Context, reader functionIntentReader, proof release.VerifiedFunction) error {
	if !proof.Valid() {
		return trust.ErrExpired
	}
	claim := proof.Claim()
	entry, err := reader.ReadFunctionIntent(ctx, claim.TenantID, claim.FunctionID)
	if err != nil {
		return err
	}
	current, err := DecodeFunctionIntent(entry)
	if err != nil {
		return err
	}
	if current.Claim.Sequence != claim.Sequence || current.EnvelopeSHA256 != proof.EnvelopeSHA256() ||
		!bytes.Equal(current.Envelope, proof.Envelope()) || !bytes.Equal(current.Delegation, proof.Delegation()) {
		return ErrConflict
	}
	if !proof.Valid() {
		return trust.ErrExpired
	}
	return nil
}

func (r *Runtime) CommitFunctionGrant(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction, binding FunctionBinding,
) (uint64, error) {
	if err := binding.Validate(); err != nil {
		return 0, err
	}
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	claim := proof.Claim()
	if catalog.OCIRegion(claim.Cell) != binding.Region {
		return 0, release.ErrExpectationMismatch
	}
	grant := FunctionGrant{TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Sequence: claim.Sequence, EnvelopeSHA256: proof.EnvelopeSHA256(), Binding: binding}
	payload, err := json.Marshal(grant)
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionGrant, binding.TaskID, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if err := r.VerifyFunctionIntent(ctx, proof); err != nil {
				return err
			}
			prior, err := r.ReadFunctionGrant(ctx, binding.TaskID)
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			if !bytes.Equal(prior.Payload, payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func (r *Reader) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func DecodeFunctionGrant(entry LogEntry) (FunctionGrant, error) {
	var grant FunctionGrant
	if err := json.Unmarshal(entry.Payload, &grant, json.RejectUnknownMembers(true)); err != nil {
		return grant, err
	}
	if _, err := functionIntentKey(grant.TenantID, grant.FunctionID); err != nil {
		return FunctionGrant{}, err
	}
	if entry.Kind != MutationFunctionGrant || entry.Sequence == 0 || entry.SubjectKey != grant.Binding.TaskID ||
		grant.Sequence == 0 || !validTerminalDigest(grant.EnvelopeSHA256) {
		return FunctionGrant{}, errors.New("function grant control-log identity is invalid")
	}
	return grant, grant.Binding.Validate()
}

func (r *Runtime) VerifyFunctionGrant(ctx context.Context, proof release.VerifiedFunction, binding FunctionBinding) error {
	return verifyFunctionGrant(ctx, r, proof, binding)
}

func (r *Reader) VerifyFunctionGrant(ctx context.Context, proof release.VerifiedFunction, binding FunctionBinding) error {
	return verifyFunctionGrant(ctx, r, proof, binding)
}

type functionGrantReader interface {
	functionIntentReader
	ReadFunctionGrant(context.Context, string) (LogEntry, error)
}

func verifyFunctionGrant(ctx context.Context, reader functionGrantReader, proof release.VerifiedFunction, binding FunctionBinding) error {
	if err := binding.Validate(); err != nil {
		return err
	}
	entry, err := reader.ReadFunctionGrant(ctx, binding.TaskID)
	if err != nil {
		return err
	}
	grant, err := DecodeFunctionGrant(entry)
	if err != nil {
		return err
	}
	claim := proof.Claim()
	if grant.TenantID != claim.TenantID || grant.FunctionID != claim.FunctionID || grant.Sequence != claim.Sequence ||
		grant.EnvelopeSHA256 != proof.EnvelopeSHA256() || grant.Binding != binding {
		return ErrConflict
	}
	return verifyFunctionIntent(ctx, reader, proof)
}

artifact_verified.text:
func ReadVerified(ctx context.Context, js jetstream.JetStream, store interface {
	GetInfo(context.Context, string, ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error)
}, bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer) error {
	if js == nil || store == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	info, err := store.GetInfo(ctx, name)
	if err != nil {
		return fmt.Errorf("inspect artifact: %w", err)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	stream, err := js.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		return fmt.Errorf("bind artifact readback stream: %w", err)
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		return stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
	})
}

artifact_chunks.text:
func validateMetadata(info *jetstream.ObjectInfo, bucket, name string, signedSize int64) error {
	if info == nil || info.Name != name || info.Bucket != bucket || info.Deleted ||
		info.Opts != nil && info.Opts.Link != nil || info.Size != uint64(signedSize) ||
		info.NUID == "" || info.Chunks == 0 || uint64(info.Chunks) > uint64(signedSize) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	return nil
}

func verifyChunks(ctx context.Context, info *jetstream.ObjectInfo, bucket, digest string, sizeLimit int64, dst io.Writer,
	get func(context.Context, uint64, string) (*jetstream.RawStreamMsg, error)) error {
	if info == nil || info.NUID == "" || info.Chunks == 0 || sizeLimit <= 0 ||
		uint64(info.Chunks) > uint64(sizeLimit) {
		return fmt.Errorf("%w: artifact chunk metadata", ErrInvalid)
	}
	storedDigest, err := jetstream.DecodeObjectDigest(info.Digest)
	if err != nil || len(storedDigest) != sha256.Size {
		return fmt.Errorf("%w: artifact object digest", ErrInvalid)
	}
	subject := "$O." + bucket + ".C." + info.NUID
	h := sha256.New()
	var size int64
	sequence := uint64(1)
	for range info.Chunks {
		if err := ctx.Err(); err != nil {
			return err
		}
		message, err := get(ctx, sequence, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return fmt.Errorf("artifact chunk is not visible: %w", jetstream.ErrObjectNotFound)
		}
		if err != nil {
			return fmt.Errorf("read artifact chunk: %w", err)
		}
		if message == nil || message.Subject != subject || message.Sequence < sequence ||
			message.Sequence == ^uint64(0) || len(message.Data) == 0 || int64(len(message.Data)) > sizeLimit-size {
			return fmt.Errorf("%w: artifact chunk sequence or size", ErrInvalid)
		}
		if _, err := dst.Write(message.Data); err != nil {
			return fmt.Errorf("spool artifact chunk: %w", err)
		}
		_, _ = h.Write(message.Data)
		size += int64(len(message.Data))
		sequence = message.Sequence + 1
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	extra, err := get(ctx, sequence, subject)
	if err == nil || extra != nil {
		return fmt.Errorf("%w: artifact has extra chunks", ErrInvalid)
	}
	if !errors.Is(err, jetstream.ErrMsgNotFound) {
		return fmt.Errorf("check artifact chunk count: %w", err)
	}
	actual := h.Sum(nil)
	if size != sizeLimit || hex.EncodeToString(actual) != digest || !bytes.Equal(actual, storedDigest) {
		return fmt.Errorf("%w: artifact bytes differ from signed digest", ErrInvalid)
	}
	return nil
}

artifact_hook.text:
func (s artifactLookupHook) GetInfo(ctx context.Context, name string, opts ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error) {
	s.before()
	return s.ArtifactStore.GetInfo(ctx, name, opts...)
}
